import{describe,it,expect}from"vitest";import fs from"fs";import path from"path";const tripPlannerJs=fs.readFileSync(path.resolve(__dirname,"../../frontend/js-modules/trip-planner.js"),"utf8"),tripPlannerHtml=fs.readFileSync(path.resolve(__dirname,"../../frontend/trip-planner/trip-planner.html"),"utf8");describe("trip-planner.js dispatches the event weather-ui.js listens for",()=>{it("dispatches tripplanner:itinerary-rendered after rendering the itinerary",()=>{expect(tripPlannerJs).toContain('new CustomEvent("tripplanner:itinerary-rendered"')})}),describe("trip-planner.html loads the full itinerary + weather-aware chain",()=>{it("loads trip-data.js and trip-planner.js",()=>{expect(tripPlannerHtml).toContain("trip-data.js"),expect(tripPlannerHtml).toContain("js-modules/trip-planner.js")}),it("loads all three weather-aware itinerary modules",()=>{expect(tripPlannerHtml).toContain("js-modules/weather-core.js"),expect(tripPlannerHtml).toContain("js-modules/weather-service.js"),expect(tripPlannerHtml).toContain("js-modules/weather-ui.js")}),it("includes the weather-planner.css stylesheet",()=>{expect(tripPlannerHtml).toContain("weather-planner.css")}),it("has the #weather-panel and #trip-start-date elements weather-ui.js requires",()=>{expect(tripPlannerHtml).toMatch(/id=["']weather-panel["']/),expect(tripPlannerHtml).toMatch(/id=["']trip-start-date["']/)}),it("actually calls initTripPlannerPage() so the form responds to input",()=>{expect(tripPlannerHtml).toContain("initTripPlannerPage()")})});